package io.github.jesterportfolio.hearth.survival;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import io.github.jesterportfolio.hearth.survival.rpg.DeathJournal;
import static org.junit.jupiter.api.Assertions.*;
class DeathJournalTest{
 @TempDir Path root;private final UUID group=UUID.randomUUID();
 @Test void orphanPreimageIsHeldAndNeverOverwritten()throws Exception{Path dir=Files.createDirectory(root.resolve("rpg-death-pending"));UUID id=UUID.randomUUID();byte[] original={1,2,3};Files.write(dir.resolve(id+".before"),original);try(var journal=new DeathJournal(root,group)){journal.open().toCompletableFuture().get(3,TimeUnit.SECONDS);assertTrue(journal.held(id));assertThrows(ExecutionException.class,()->journal.acquire(id,"a".repeat(64),"b".repeat(64),new byte[]{4}).toCompletableFuture().get());assertArrayEquals(original,Files.readAllBytes(dir.resolve(id+".before")));}}
 @Test void cleanupIntentSurvivesInterruptionWithBothHardLinks()throws Exception{UUID id=UUID.randomUUID();try(var journal=new DeathJournal(root,group)){journal.open().toCompletableFuture().get();journal.acquire(id,"a".repeat(64),"b".repeat(64),new byte[]{1}).toCompletableFuture().get();journal.drain().toCompletableFuture().get();}Path dir=root.resolve("rpg-death-pending");Files.createLink(dir.resolve(id+".done"),dir.resolve(id+".pending"));try(var next=new DeathJournal(root,group)){next.open().toCompletableFuture().get();assertFalse(next.held(id));try(var paths=Files.list(dir)){assertEquals(0,paths.count());}}}
 @Test void normalCleanupAndConcurrentRequestHaveSingleWinner()throws Exception{UUID id=UUID.randomUUID();try(var journal=new DeathJournal(root,group)){journal.open().toCompletableFuture().get();var first=journal.acquire(id,"a".repeat(64),"b".repeat(64),new byte[]{7});var second=journal.acquire(id,"a".repeat(64),"b".repeat(64),new byte[]{8});assertThrows(ExecutionException.class,()->second.toCompletableFuture().get());var ticket=first.toCompletableFuture().get();ticket.clean().toCompletableFuture().get();assertFalse(journal.held(id));}try(var restored=new DeathJournal(root,group)){restored.open().toCompletableFuture().get();assertTrue(restored.heldPlayers().isEmpty());}}
 @Test void conflictingCompletionAndPendingRecordsArePreservedForReview()throws Exception{UUID id=UUID.randomUUID();try(var journal=new DeathJournal(root,group)){journal.open().toCompletableFuture().get();journal.acquire(id,"a".repeat(64),"b".repeat(64),new byte[]{1}).toCompletableFuture().get();}Path dir=root.resolve("rpg-death-pending");Files.copy(dir.resolve(id+".pending"),dir.resolve(id+".done"));try(var next=new DeathJournal(root,group)){next.open().toCompletableFuture().get();assertTrue(next.held(id));assertTrue(Files.exists(dir.resolve(id+".before")));assertTrue(Files.exists(dir.resolve(id+".pending")));}}
}
